-- V1: esquema inicial, EMITIDO PELO HIBERNATE a partir das 21 entidades geradas do mapa (2026-11-21, Quarkus 3.33.4.2,
-- PostgreSQL 17) e congelado aqui. Ate o primeiro banco REAL existir, esta migracao e regerada junto com o codigo; depois
-- disso ela e IMUTAVEL (o Flyway confere o checksum) e toda mudanca de esquema entra em uma migracao nova (V3, V4...).
-- O Hibernate so VALIDA o esquema; nunca cria nem altera tabelas.
create table ASSINATURAEMPRESA (DATA_FIM date, DATA_INICIO date, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), ESTADO varchar(10), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, PLANO_ID varchar(36) not null, VINCULADA_POR_ID varchar(36), REFERENCIA_CRM varchar(50), primary key (ID));
create table ATIVIDADEEMPRESA (CODIGO_CNAE varchar(7), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), TIPO varchar(10), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, DESCRICAO varchar(300), primary key (ID));
create table CANCELAMENTO (CODIGO_MOTIVO integer, CODIGO_RETORNO integer, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_HORA_APROVACAO timestamp(6), DATA_HORA_EVENTO timestamp(6), DATA_HORA_RECUSA timestamp(6), VERSION timestamp(6), AMBIENTE varchar(15), ESTADO varchar(25), APROVADO_POR_ID varchar(36), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, NOTA_ID varchar(36) not null, PREPARADO_POR_CLIENTE_ID varchar(36), PREPARADO_POR_USUARIO_ID varchar(36), RECUSADO_POR_ID varchar(36), MENSAGEM_RETORNO varchar(500), PDF bytea, XML bytea, MOTIVO varchar(255), primary key (ID));
create table CHAMADAGATEWAY (CODIGO_HTTP integer, CODIGO_RETORNO integer, DURACAO_MS integer, VERSAO_API varchar(5), METODO_HTTP varchar(7), DATA_ATUALIZACAO timestamp(6), DATA_CHAMADA timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), AMBIENTE varchar(15), OPERACAO varchar(30), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, NOTA_ID varchar(36), IDENTIFICACAO varchar(40), CHAVE varchar(50), ROTA varchar(200), MENSAGEM_RETORNO varchar(500), RESUMO_ENVIO varchar(500), primary key (ID));
create table CLIENTEACESSO (ATIVO boolean, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_EXPIRACAO timestamp(6), DATA_ULTIMO_USO timestamp(6), VERSION timestamp(6), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, CLIENT_ID varchar(64), SCOPES varchar(100), NOME varchar(120), SEGREDO_HASH varchar(255), primary key (ID));
create table CONFIRMACAOCADASTRO (DATA_ATUALIZACAO timestamp(6), DATA_CONFIRMACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_EXPIRACAO timestamp(6), VERSION timestamp(6), ESTADO varchar(10), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, USUARIO_ID varchar(36) not null, EMAIL varchar(160), TOKEN_HASH varchar(255), primary key (ID));
create table CONTATO (DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), TIPO_CONTATO varchar(10), WHATSAPP varchar(20), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, PESSOA_ID varchar(36) not null, EMAIL varchar(60), NOME varchar(300), primary key (ID));
create table EMPRESA (REGIME_IBS_CBS integer, REGIME_TRIBUTARIO integer, VALIDADE_CERTIFICADO date, CEP varchar(8), DATA_ATUALIZACAO timestamp(6), DATA_CADASTRO_GATEWAY timestamp(6), DATA_CONFIRMACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), DOCUMENTO varchar(14), TELEFONE varchar(14), AMBIENTE varchar(15), INSCRICAO_MUNICIPAL varchar(20), RG_INSCRICAO_ESTADUAL varchar(20), SITUACAO varchar(20), SITUACAO_CERTIFICADO varchar(20), STATUS_CADASTRO varchar(20), WHATSAPP varchar(20), ID varchar(36) not null, MUNICIPIO_ID varchar(36) not null, REFERENCIA_CRM varchar(50), BAIRRO varchar(60), COMPLEMENTO varchar(60), EMAIL varchar(60), LOGRADOURO varchar(60), NOME_FANTASIA varchar(60), NUMERO_ENDERECO varchar(60), RAZAO_SOCIAL varchar(60), REFERENCIA_CERTIFICADO varchar(100), REFERENCIA_CREDENCIAIS_PREFEITURA varchar(100), REFERENCIA_TOKEN_EMPRESA varchar(100), URL_WEBHOOK varchar(200), LOGO bytea, primary key (ID));
create table EVENTOWEBHOOK (CODIGO integer, SUCESSO boolean, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_PROCESSAMENTO timestamp(6), DATA_RECEBIMENTO timestamp(6), VERSION timestamp(6), CNPJ_CPF varchar(14), AMBIENTE varchar(15), ESTADO_PROCESSAMENTO varchar(15), RESULTADO_ASSINATURA varchar(15), ORIGEM varchar(30), TIPO varchar(30), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, NOTA_ID varchar(36), IDENTIFICACAO varchar(40), CHAVE varchar(50), MENSAGEM varchar(500), primary key (ID));
create table FATURACRM (DATA_EMISSAO date, DATA_PAGAMENTO date, DATA_VENCIMENTO date, VALOR numeric(15,2), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_SINCRONIZACAO timestamp(6), VERSION timestamp(6), ESTADO varchar(10), NUMERO varchar(30), ASSINATURA_ID varchar(36), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, CRM_FATURA_ID varchar(50), LINK_FATURA varchar(500), primary key (ID));
create table HISTORICOSITUACAOEMPRESA (DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_HORA timestamp(6), VERSION timestamp(6), ORIGEM varchar(20), SITUACAO_ANTERIOR varchar(20), SITUACAO_NOVA varchar(20), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, RESPONSAVEL_ID varchar(36), MOTIVO varchar(500), primary key (ID));
create table IMPORTACAOMUNICIPIO (LINHAS_ATUALIZADAS integer, LINHAS_IGUAIS integer, LINHAS_INSERIDAS integer, LINHAS_LIDAS integer, LINHAS_REJEITADAS integer, SEPARADOR_DETECTADO varchar(5), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_HORA_FIM timestamp(6), DATA_HORA_INICIO timestamp(6), VERSION timestamp(6), CODIFICACAO_DETECTADA varchar(20), ESTADO varchar(23), ID varchar(36) not null, USUARIO_ID varchar(36) not null, RESUMO_REJEICOES varchar(4000), NOME_ARQUIVO varchar(255), primary key (ID));
create table MUNICIPIO (UF varchar(2), CODIGO_IBGE varchar(7), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), ID varchar(36) not null, NOME varchar(100), primary key (ID));
create table NOTA (ALIQUOTA_COFINS numeric(5,2), ALIQUOTA_ISS numeric(5,2), ALIQUOTA_PIS numeric(5,2), CODIGO_RETORNO integer, CODIGO_TRIBUTACAO_MUNICIPIO varchar(3), CST_PIS_COFINS varchar(2), DATA_COMPETENCIA date, ISS_RETIDO boolean, REGIME_APURACAO integer, REGIME_TRIBUTACAO integer, RESPONSAVEL_RETENCAO integer, TIPO_OPERACAO_ISS integer, TIPO_RETENCAO integer, VALOR_BASE_CALCULO numeric(15,2), VALOR_COFINS numeric(15,2), VALOR_CSLL numeric(15,2), VALOR_DESCONTO_CONDICIONADO numeric(15,2), VALOR_DESCONTO_INCONDICIONADO numeric(15,2), VALOR_INSS numeric(15,2), VALOR_IR numeric(15,2), VALOR_PIS numeric(15,2), VALOR_RECEBIDO numeric(15,2), VALOR_SERVICOS numeric(15,2), RPS_SERIE varchar(5), SERIE varchar(5), CODIGO_SERVICO varchar(6), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_EMISSAO timestamp(6), DATA_HORA_APROVACAO timestamp(6), DATA_HORA_DESCARTE timestamp(6), DATA_HORA_EVENTO timestamp(6), VERSION timestamp(6), CODIGO_NBS varchar(9), NUMERO varchar(9), RPS_NUMERO varchar(9), AMBIENTE varchar(15), ESTADO varchar(20), NUMERO_NFSE varchar(20), APROVADO_POR_ID varchar(36), DESCARTADO_POR_ID varchar(36), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, PESSOA_ID varchar(36) not null, PREPARADO_POR_CLIENTE_ID varchar(36), PREPARADO_POR_USUARIO_ID varchar(36), SERVICO_ID varchar(36) not null, CODIGO_VERIFICACAO varchar(40), CHAVE varchar(50), DESCRICAO varchar(200), LINK_PDF varchar(500), MENSAGEM_RETORNO varchar(500), DISCRIMINACAO varchar(2000), INFORMACOES_COMPLEMENTARES varchar(2000), ERROS_RETORNO varchar(4000), PDF bytea, XML bytea, primary key (ID));
create table PESSOA (CODIGO_PAIS varchar(4), CONSUMIDOR_FINAL boolean, TIPO_DESTINATARIO integer, CEP varchar(8), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), TIPO_PESSOA varchar(10), CODIGO_POSTAL varchar(11), DOCUMENTO varchar(14), INSCRICAO_MUNICIPAL varchar(15), RG_INSCRICAO_ESTADUAL varchar(20), TELEFONE varchar(20), CIDADE_ID varchar(36), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, BAIRRO varchar(60), EMAIL varchar(60), NOME_MUNICIPIO_EXTERIOR varchar(60), NOME_PROVINCIA varchar(60), NUMERO_ENDERECO varchar(60), COMPLEMENTO varchar(256), NOME varchar(300), NOME_FANTASIA varchar(300), LOGRADOURO varchar(255), primary key (ID));
create table PLANO (ATIVO boolean, VALOR numeric(15,2), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), PERIODICIDADE varchar(10), ID varchar(36) not null, REFERENCIA_CRM varchar(50), NOME varchar(100), DESCRICAO varchar(500), primary key (ID));
create table QSAEMPRESA (DATA_ENTRADA_SOCIEDADE date, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), CPF varchar(14), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, QUALIFICACAO varchar(100), NOME varchar(300), primary key (ID));
create table SERVICO (ALIQUOTA_ISS numeric(5,2), ATIVO boolean, CODIGO_TRIBUTACAO_MUNICIPIO varchar(3), CST_PIS_COFINS varchar(2), ISS_RETIDO boolean, TIPO_OPERACAO_ISS integer, VALOR_PADRAO numeric(15,2), CODIGO_SERVICO varchar(6), DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), CODIGO_NBS varchar(9), CODIGO_INTERNO varchar(20), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, NOME varchar(100), DESCRICAO_CURTA varchar(200), DISCRIMINACAO_PADRAO varchar(2000), primary key (ID));
create table TOKENRENOVACAO (REVOGADO boolean, USADO boolean, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_EXPIRACAO timestamp(6), DATA_REVOGACAO timestamp(6), DATA_USO timestamp(6), VERSION timestamp(6), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, USUARIO_ID varchar(36) not null, TOKEN_HASH varchar(255), primary key (ID));
create table USUARIO (ADMINISTRADOR_PLATAFORMA boolean, ATIVO boolean, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), DATA_ULTIMO_ACESSO timestamp(6), VERSION timestamp(6), WHATSAPP varchar(20), ID varchar(36) not null, NOME varchar(120), EMAIL varchar(160), SENHA_HASH varchar(255), primary key (ID));
create table VINCULOUSUARIO (ATIVO boolean, DATA_ATUALIZACAO timestamp(6), DATA_CRIACAO timestamp(6), VERSION timestamp(6), PAPEL varchar(15), EMPRESA_ID varchar(36) not null, ID varchar(36) not null, USUARIO_ID varchar(36) not null, primary key (ID));
